local s_vsh = [[
attribute vec2 vPosition;
varying vec2 vUV0;
void main()
{
    gl_Position = vec4(vPosition, 0.0, 1.0);
    //An opportunism code. Do not use it unless you know what it means.
    vUV0 = (vPosition.xy + 1.0) / 2.0;
}
]]

local s_fsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

    uniform sampler2D inputImageTexture;
    uniform vec2 uMainTexSize;
    uniform float uCenterX;
    uniform float uCenterY;
    uniform float uSize;
    uniform float uConvergence;

    varying vec2 vUV0;

    void main()
    {
        vec2 dir = (vUV0 - vec2(uCenterX, uCenterY))* vec2(1.0, uMainTexSize.y / uMainTexSize.x);

        float r2 = dot(dir, dir);
        r2 = r2 * (pow(2.0, (100.0-uSize) * 0.1)- 1.0) * pow(5.0, max((100.0 - uSize) * 0.1 - 5.0, 0.0));

        if(sqrt(r2)< 1.0)
        {
            float fac = r2 * (-uConvergence) * 0.01;
            fac = (1.0 + fac);
            
            dir = dir * vec2(1.0, uMainTexSize.x / uMainTexSize.y);
            vec2 nUV = vec2(uCenterX, uCenterY) + dir * fac;
            vec2 lt = step(vec2(0.0, 0.0), nUV);
            vec2 rb = step(nUV, vec2(1.0, 1.0));
            gl_FragColor = mix(vec4(0.0), texture2D(inputImageTexture, nUV), step(2.0, dot(lt, rb)));
        }
        else
        {
			gl_FragColor = vec4(0.0, 0.0, 0.0, 0.0);
		}
    }
]]

